INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 1, 'Упражнения: множества');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 0, 'Сколько подмножеств у пустого множества?', '["1"]', 'Подставьте ноль элементов в 2ⁿ.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 1, 'Множество записано перечислением: «два, один, один». Сколько в нём элементов?', '["2"]', 'Повторы в множестве схлопываются в один элемент.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 2, 'В множестве A четыре элемента, в множестве B шесть, а в их пересечении один. Сколько элементов в объединении A и B?', '["9"]', 'Наивная сумма посчитает общий элемент дважды — уберите один лишний.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 3, 'У приложения 10 подписчиков, и 4 из них уже друзья. Сколько подписчиков входят в разность «подписчики минус друзья»?', '["6"]', 'Разность — то, что есть в первом множестве и отсутствует во втором.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 4, 'Известно, что неверно, что выполняется хотя бы одно из двух условий. Означает ли это, что не выполняются оба условия?', '["да","истинно"]', 'Это закон де Моргана: отрицание переворачивает «или» в «и».');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 5, 'Сколько подмножеств у множества из 5 элементов?', '["32"]', 'Для каждого из пяти элементов решаете: брать или нет. Два выбора на элемент.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 6, 'Программист перебирает все подмножества 10-элементного множества, пропуская пустое и само полное множество. Сколько вариантов останется?', '["1022"]', 'Всего подмножеств 1024 — из главы. Вычтите два исключённых случая.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 2, 'Упражнения: отношения и функции');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 0, 'Три футболки и двое брюк. Сколько нарядов содержит прямое произведение?', '["6"]', 'Каждый независимый выбор перемножается: 3 × 2.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 1, 'В одном множестве 5 элементов, во втором 4. Сколько пар в их прямом произведении?', '["20"]', 'Число пар — произведение мощностей.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 2, 'Отношение «меньше» на числах рефлексивно?', '["нет","ложно"]', 'Рефлексивность значит: каждый элемент связан с самим собой. Число не меньше самого себя.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 3, 'Отношение «подписан» в соцсети симметрично?', '["нет","ложно"]', 'Симметрия: если первый связан со вторым, то и второй с первым. Блогер может вас не читать.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 4, 'Отношение «является предком» транзитивно?', '["да","истинно"]', 'Проверьте цепочку: предок предка — тоже предок?');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 5, 'Функция читает текущее время и на его основе возвращает результат. Является ли она чистой?', '["нет","ложно"]', 'Чистая функция зависит только от аргументов и не смотрит на внешний мир.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 6, 'Может ли функция быть одновременно инъекцией и сюръекцией?', '["да","истинно"]', 'У такого соответствия есть отдельное имя — и оно обратимо.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 7, '8 гостей рассадили по 10 стульям, каждый гость сидит ровно на одном стуле. Может ли отображение «гость → стул» быть сюръекцией?', '["нет","ложно"]', 'Сюръекция требует, чтобы каждый стул был занят. Сосчитайте максимальное число занятых стульев.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 3, 'Упражнения: комбинаторика');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 0, 'Сколько разных пин-кодов из четырёх цифр, если на каждой позиции любая из десяти цифр?', '["10000"]', 'Десять вариантов на каждую из четырёх позиций — правило произведения.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 1, 'Чему равно 4! (факториал)?', '["24"]', 'Перемножьте все числа от 1 до 4.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 2, 'Во сколько раз увеличится пространство паролей при удлинении пароля на один символ, если алфавит — 95 печатных знаков?', '["95"]', 'Каждый новый символ умножает пространство на размер алфавита.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 3, 'Конференция из 5 докладов. Сколькими способами можно расставить порядок выступлений?', '["120"]', 'Это перестановка: 5!.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 4, '20 спортсменов борются за золото, серебро и бронзу. Сколько вариантов распределения наград?', '["6840"]', 'Порядок важен: 20 × 19 × 18.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 5, 'Сколько способов выбрать двух ревьюеров из шести в пуле, если порядок не важен?', '["15"]', 'Это C(6,2): шесть на первое место, пять на второе, и делите на перестановки пары.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 6, '10 человек в комнате пожимают друг другу руки, каждый с каждым ровно раз. Сколько рукопожатий?', '["45"]', 'Число пар без повторов: C(10,2) = 10 × 9 / 2.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 7, 'Сколько пин-кодов из четырёх цифр без повторяющихся цифр?', '["5040"]', 'Это размещение: 10! / 6!, то есть 10 × 9 × 8 × 7.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 4, 'Упражнения: бином, Паскаль и Дирихле');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 0, 'Сумма всех чисел строки треугольника Паскаля, отвечающей множеству из 6 элементов, равна 2⁶. Сколько это?', '["64"]', 'Степень двойки: шесть двоек, перемноженных между собой.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 1, 'Какой коэффициент стоит при a²b² в разложении (a + b)⁴?', '["6"]', 'Коэффициенты бинома — строка Паскаля «1, 4, 6, 4, 1». Или посчитайте C(4,2).');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 2, 'Пользуясь симметрией строки, найдите C(6,5).', '["6"]', 'Выбрать пятерых, кого взять, — то же, что выбрать одного, кого оставить: C(6,1).');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 3, 'Аудиокурс начали 40 человек, вебинар смотрели 30, и 10 человек сделали и то и другое. Сколько человек охвачено хотя бы чем-то одним?', '["60"]', 'Десять человек посчитаны дважды — вычтите их один раз.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 4, 'В хеш-таблице 10 ячеек. Сколько элементов нужно вставить, чтобы коллизия стала гарантированной?', '["11"]', 'Кроликов должно стать больше, чем клеток.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 5, 'Сколько пар-кандидатов на совпадение дней рождения в группе из 23 человек? Это C(23,2).', '["253"]', '23 × 22, разделить пополам.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 6, 'Из 100 человек английский знают 55, немецкий 45, французский 25; попарные пересечения: 18, 12 и 8; все три языка — 5. Сколько человек не знают ни одного из трёх языков?', '["8"]', 'Сначала включения-исключения: сумма минус попарные плюс тройное. Потом вычтите результат из 100.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 5, 'Упражнения: логика высказываний');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 0, 'Сколько строк в таблице истинности формулы от двух переменных?', '["4"]', 'Две переменные, каждая — два значения: 2².');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 1, 'Сколько строк в таблице истинности формулы от трёх переменных?', '["8"]', '2³ — тот же счёт, что у булеана.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 2, 'Высказывание «если два больше трёх, то я балерина» формально истинно?', '["да","истинно"]', 'Посылка ложна — а что происходит с импликацией при ложной посылке?');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 3, 'Утверждение «все элементы массива удовлетворяют условию» на пустом массиве возвращает истину?', '["да","истинно"]', 'Нет элементов — нет и нарушителей.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 4, 'Математическое «или» истинно в случае, когда обе его части истинны?', '["да","истинно"]', 'Математическое «или» — включающее, а не исключающее.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 5, 'В выражении «a и b» при коротком замыкании левая часть a оказалась ложной. Будет ли вычислена правая часть b?', '["нет","ложно"]', '«И» уже знает исход: ложный левый операнд решает всё.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 6, 'Сколько строк в таблице истинности формулы от пяти переменных?', '["32"]', '2⁵ — полное перечисление всех комбинаций значений.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 7, 'Противоречие — формула «дождь и не дождь одновременно». Сколько строк её таблицы истинности, в которых она истинна?', '["0"]', 'Противоречие ложно во всех строках — сосчитайте, в скольких оно истинно.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 6, 'Упражнения: предикаты и кванторы');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 0, 'Предикат «возраст больше 18» при значении 20 истинен?', '["да","истинно"]', 'Подставьте значение в предикат — получите обычное высказывание.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 1, 'Массив [2, 4, 6]. Утверждение «каждый элемент массива чётный» истинно?', '["да","истинно"]', 'Это квантор всеобщности по конечному множеству — проверьте каждый элемент.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 2, 'Массив [2, 4]. Утверждение «найдётся нечётный элемент» истинно?', '["нет","ложно"]', 'Квантор существования требует хотя бы одного подходящего элемента.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 3, 'Известно, что не все пассажиры пристёгнуты. Следует ли из этого, что найдётся расстёгнутый пассажир?', '["да","истинно"]', 'Отрицание квантора всеобщности меняет его на противоположный.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 4, 'Известно, что среди гостей нет ни одного вегетарианца. Следует ли, что каждый гость не вегетарианец?', '["да","истинно"]', 'Отрицание квантора существования меняет его на квантор всеобщности.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 5, 'Метод every с предикатом p вернул false. Гарантирует ли это, что some с отрицательным предикатом вернёт true?', '["да","истинно"]', '«Не для всех элементов p истинен» = «найдётся элемент, для которого p ложен».');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 6, 'Утверждения «для каждого запроса найдётся свой обработчик» и «найдётся один обработчик для всех запросов» означают одно и то же?', '["нет","ложно"]', 'Порядок кванторов меняет смысл: во втором случае обработчик выбирается один на всех.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 7, 'Массив [1, 3, 5]. Утверждение «для каждого элемента массива найдётся в нём элемент больше него» истинно?', '["нет","ложно"]', 'Проверьте максимальный элемент: найдётся ли для него больший?');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 7, 'Упражнения: индукция и рекуррентности');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 0, 'Чему равна сумма всех чисел от 1 до 4?', '["10"]', '1 + 2 + 3 + 4. Или формула n(n+1)/2.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 1, 'Чему равна сумма всех чисел от 1 до 100? Как считал Гаусс: 100 × 101 пополам.', '["5050"]', 'Сложите 100 и 101, разделите пополам.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 2, 'Числа Фибоначчи: F(1) = 1, F(2) = 1, каждый следующий — сумма двух предыдущих. Чему равно F(5)?', '["5"]', 'Выпишите по порядку: 1, 1, и дальше суммируйте пары.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 3, 'В сильной индукции переход может опираться на все предыдущие значения сразу, а не только на соседнее. Верно ли это?', '["да","истинно"]', 'У лестницы сильной индукции просто больше опорных ступеней.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 4, 'Сортировка слиянием делит массив из 8 элементов пополам до кусков по одному. Сколько уровней деления?', '["3"]', '8 → 4 → 2 → 1. Сосчитайте стрелки.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 5, 'Быстрая сортировка каждый раз выбирает крайним опорный элемент: массив из 100 элементов превращается в 99, потом в 98. Сколько уровней рекурсии в этом худшем случае?', '["100"]', 'Массив уменьшается ровно на один элемент за уровень — от 100 до нуля.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 6, 'Инвариант цикла должен быть верен перед каждой итерацией и после каждой. Верно ли это?', '["да","истинно"]', 'Перед первым витком — база, сохранение за витком — переход.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 7, 'Сортировка слиянием на массиве из 8 элементов: уровней деления 3, и на каждом уровне суммарная работа по всем кускам равна 8. Сколько всего единиц работы?', '["24"]', 'Умножьте работу одного уровня на число уровней: 8 × 3.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 8, 'Упражнения: графы');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 0, 'Сумма степеней всех вершин неориентированного графа равна 20. Сколько в нём рёбер?', '["10"]', 'Лемма о рукопожатиях: сумма степеней равна удвоенному числу рёбер.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 1, 'В ориентированном графе 7 стрелок. Чему равна сумма входящих степеней всех вершин?', '["7"]', 'Каждая стрелка входит ровно один раз.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 2, 'Может ли в графе быть ровно одна вершина нечётной степени?', '["нет","ложно"]', 'Сумма степеней всегда чётна — что из этого следует для числа нечётных слагаемых?');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 3, 'Пакет a требует b, b требует c, а c требует a. Существует ли корректный порядок установки этих пакетов?', '["нет","ложно"]', 'В графе зависимостей цикл — синоним беды.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 4, 'Неориентированный граф: 3 вершины, соединённые попарно (3 ребра), петель нет. Сколько единиц в его матрице смежности?', '["6"]', 'Каждое ребро даёт две единицы: на пересечении пары в обе стороны.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 5, 'Может ли сумма степеней всех вершин неориентированного графа равняться 21?', '["нет","ложно"]', 'Сумма степеней — это удвоенное число рёбер. Может ли удвоенное число быть нечётным?');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 6, 'В неориентированном графе 4 вершины со степенями 1, 2, 3 и 4. Сколько в нём рёбер?', '["5"]', 'Сначала сложите степени, потом вспомните про удвоение.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 9, 'Упражнения: обходы и деревья');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 0, 'Сколько рёбер в дереве с 10 вершинами?', '["9"]', 'У дерева формула: рёбер ровно n − 1.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 1, 'Обход в глубину естественно держать стеком, а обход в ширину — очередью. Верно ли это?', '["да","истинно"]', 'Глубина идёт до упора и отступает; ширина расходится волной по кругам.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 2, 'Обход в ширину находит кратчайшие пути в графе без весов. Верно ли это?', '["да","истинно"]', 'Волна сначала проверяет всех на расстоянии один, потом на расстоянии два.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 3, 'Граф из 5 вершин: есть рёбра 1–2 и 3–4, вершина 5 ни с кем не соединена. Сколько компонент связности?', '["3"]', 'Компонента — остров достижимых друг для друга вершин. Сосчитайте острова: {1,2}, {3,4} и...');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 4, 'В кёнигсбергской задаче было 4 вершины нечётной степени. Возможно ли там пройти по каждому мосту ровно один раз?', '["нет","ложно"]', 'Эйлеров путь существует только при нуле или двух нечётных вершинах.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 5, 'Связный граф с 7 вершинами и 6 рёбрами. Гарантированно ли в нём нет циклов?', '["да","истинно"]', 'Сравните число рёбер с n − 1: если совпало у связного графа, перед вами дерево.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 6, 'Нужно связать 20 серверов кабелями так, чтобы сеть была связной и без лишних циклов (остовное дерево). Какое минимальное число каналов потребуется?', '["19"]', 'Скелет сети — дерево: рёбер ровно n − 1.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 10, 'Упражнения: вероятность и Байес');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 0, 'Игральная кость: какова вероятность выпадения чётного числа?', '["0.5","0,5","1/2"]', 'Благоприятных граней три из шести — разделите.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 1, 'Бросают 5 монет. Сколько всего исходов у этого опыта?', '["32"]', 'Каждая монета удваивает варианты: 2⁵.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 2, 'Монету бросают дважды. Какова вероятность, что оба раза выпадет решка?', '["0.25","0,25","1/4"]', 'Броски независимы: перемножьте 1/2 и 1/2.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 3, 'P(A) = 0.5, P(B) = 0.2, вероятность обоих сразу 0.1. Какова вероятность, что случится A или B?', '["0.6","0,6"]', 'Сумма вероятностей минус вероятность пересечения.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 4, 'События «выпало чётное» и «выпало три» несовместны. Независимы ли они?', '["нет","ложно"]', 'Узнав про три, вы точно знаете, что не чётное. Зависимость — это про информацию.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 5, 'В группе из 23 человек вероятность, что найдутся двое с одним днём рождения, больше 50 процентов?', '["да","истинно"]', 'Интуиция считает людей, а надо считать пары — их почти двести пятьдесят.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 6, 'Болезнью болеет 1 человек из 1000. Тест ловит больного в 99 случаях из 100, но здорового ошибочно помечает в 1 случае из 100. Тест положительный. Сколько примерно процентов составляет вероятность болезни (округлите до целого)?', '["9"]', 'На сто тысяч человек: около ста больных тест поймает, но и около тысячи здоровых пометит ложно. Сравните эти числа.');
